/** #/demo/<screen>: fills the example records on a fresh device, then opens the screen (ui/demoLink.ts). */
import { useEffect } from 'preact/hooks';
import { actions, getState } from '../../data/store';
import { activeSubject } from '../../data/subjects';
import { demoTarget, shouldLoadDemo } from '../demoLink';

export function DemoLink({ to }: { to?: string }) {
  useEffect(() => {
    let live = true;
    void (async () => {
      if (shouldLoadDemo(!!getState().profile, activeSubject())) await actions.loadDemo();
      if (!live) return;
      const target = demoTarget(to, getState().sessions.at(-1)?.id ?? null);
      // Replace the link in the history, so going back does not land on it again.
      history.replaceState(null, '', `#${target}`);
      window.dispatchEvent(new HashChangeEvent('hashchange'));
    })();
    return () => {
      live = false;
    };
  }, [to]);
  return <div class="splash">예시 화면을 여는 중…</div>;
}
