/**
 * One-tap links from the intro page (#/demo/<screen>, SRS-USA-010): a device without records gets the example
 * records first, then the screen opens. A device with its own records, or with a research subject's records open, is
 * never changed: the link only opens the screen.
 */
export type DemoScreen = 'result' | 'stretch' | 'rehab' | 'assess';

/** The featured stretch of the intro page (작은광대근, the zyg-minor clip). */
export const DEMO_STRETCH = 'cheek-guide';

/** Fill the example records only on a device that has none (and no research subject open). */
export const shouldLoadDemo = (hasProfile: boolean, subject: string | null): boolean => !hasProfile && !subject;

/** The app route a demo link opens. */
export function demoTarget(to: string | undefined, lastSessionId: string | null): string {
  switch (to) {
    case 'result':
      return lastSessionId ? `/session/${lastSessionId}` : '/';
    case 'stretch':
      return `/exercise/${DEMO_STRETCH}`;
    case 'rehab':
      return '/rehab/all';
    case 'assess':
      return '/assess';
    default:
      return '/';
  }
}
